import Link from "next/link";
import { IconCheck } from "./icons";
import { planTip, planAudience } from "./planTips";

export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
};

function money(cents: number) {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}

function planFeatures(p: PlanCard): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  return [
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    "Full root access",
    "Free DDoS protection",
  ];
}

export function PricingGrid({ plans }: { plans: PlanCard[] }) {
  // Highlight the middle plan (by position) as "Most popular".
  const popularIdx = plans.length ? Math.floor((plans.length - 1) / 2) : -1;

  if (plans.length === 0) {
    return (
      <div className="card text-center text-slate-400">
        Plans are being provisioned. Please check back shortly.
      </div>
    );
  }

  return (
    <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
      {plans.map((p, i) => {
        const popular = i === popularIdx;
        return (
          <div
            key={p.id}
            className={`group relative flex flex-col rounded-2xl border p-6 backdrop-blur-md transition-all duration-300 hover:-translate-y-1.5 ${
              popular
                ? "border-brand-500/40 bg-navy-850/80 glow-brand"
                : "border-white/[0.06] bg-navy-900/70 hover:border-brand-500/30 hover:bg-navy-850/70 hover:shadow-[0_0_40px_-10px_rgb(111_71_245_/_0.4)]"
            }`}
          >
            {popular && (
              <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-gradient-to-r from-accent-blue to-brand-500 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-white shadow-lg">
                Most popular
              </span>
            )}
            <div className="flex items-center justify-between">
              <h3 className="text-base font-semibold text-white">{p.name}</h3>
              <span className="rounded-full border border-brand-500/30 bg-brand-500/10 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-brand-300">
                {planAudience(p)}
              </span>
            </div>
            <div className="mt-3 flex items-end gap-1">
              <span className="text-4xl font-bold tracking-tight">{money(p.priceCents)}</span>
              <span className="mb-1 text-sm text-slate-400">/mo</span>
            </div>
            <div className="mt-4 flex items-start gap-2 rounded-xl border border-white/[0.06] bg-white/[0.02] px-3 py-2.5">
              <span className="mt-0.5 text-brand-300" aria-hidden>
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                  <path d="M9 18h6M10 21h4M12 2a7 7 0 0 0-4 12.7c.6.5 1 1.3 1 2.1h6c0-.8.4-1.6 1-2.1A7 7 0 0 0 12 2z" />
                </svg>
              </span>
              <p className="text-[12px] leading-snug text-slate-300">
                <span className="font-semibold text-slate-200">Great for: </span>
                {planTip(p)}
              </p>
            </div>
            <ul className="mt-5 flex-1 space-y-3 text-sm">
              {planFeatures(p).map((f) => (
                <li key={f} className="flex items-center gap-2.5 text-slate-300">
                  <span className="flex h-4.5 w-4.5 shrink-0 items-center justify-center rounded-full bg-brand-500/15 text-brand-300">
                    <IconCheck size={12} />
                  </span>
                  {f}
                </li>
              ))}
            </ul>
            <Link
              href="/register"
              className={`mt-7 w-full ${popular ? "btn-primary" : "btn-secondary"}`}
            >
              Deploy now
            </Link>
          </div>
        );
      })}
    </div>
  );
}

===actions-email-hosting.ts===
"use server";

import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths } from "./billing-terms";
import { encryptSecret } from "./crypto-box";
import {
  mailcowConfigured,
  mcCreateDomain,
  mcDomainExists,
  mcCreateMailbox,
  mcDeleteMailbox,
  mcSetMailboxActive,
} from "./mailcow";

/**
 * Business Email — mailbox hosting per registered domain.
 *
 * An `EmailPlan` is a pricing tier (N mailboxes, GB/mailbox, price, term). A
 * customer subscribes one of their own domains to a tier (`EmailSubscription`),
 * which debits the wallet, then manages individual `Mailbox` rows under it.
 *
 * Mail delivery runs through a self-hosted Mailcow server, reached via lib/mailcow.ts
 * (config from MAILCOW_API_URL / MAILCOW_API_KEY). Creating a Mailbox row records
 * intent (status PROVISIONING); we then attempt to provision the real mailbox on
 * Mailcow and flip the row to ACTIVE, or FAILED if the call errors. All Mailcow
 * calls are additive and failure-tolerant — a Mailcow outage never breaks the
 * order flow; the row persists and can be retried via retryMailboxProvision.
 *
 * This module owns:
 *   - orderEmailHosting (customer subscribe)
 *   - addMailbox / removeMailbox / retryMailboxProvision (customer mailbox management)
 *   - adminSaveEmailPlan / adminToggleEmailPlan / adminDeleteEmailPlan (CRUD)
 */

type Result = { error?: string; ok?: boolean };

/**
 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
 * can be picked up once the integration is wired.
 */
async function provisionMailboxOnMailcow(mailbox: {
  id: string;
  address: string;
  quotaMB: number | null;
  subscription: { domainName: string };
}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
  if (!mailcowConfigured()) return "PROVISIONING";

  const [localPart] = mailbox.address.split("@");
  const domain = mailbox.subscription.domainName;
  const quotaMB = mailbox.quotaMB ?? 1024;

  try {
    // Ensure the mail domain exists before adding the mailbox.
    if (!(await mcDomainExists(domain))) {
      // A concurrent create or pre-existing domain can still error here; ignore
      // and let the mailbox add be the real signal.
      await mcCreateDomain(domain).catch(() => {});
    }

    const password = randomBytes(18).toString("base64url");
    await mcCreateMailbox({
      localPart,
      domain,
      name: mailbox.address,
      password,
      quotaMB,
    });

    await db.mailbox.update({
      where: { id: mailbox.id },
      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
    });
    return "ACTIVE";
  } catch (e) {
    await db.mailbox
      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
      .catch(() => {});
    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
    return "FAILED";
  }
}

// ---------- Admin CRUD (billing area) ----------

const planSchema = z.object({
  id: z.string().optional(),
  name: z.string().min(2).max(80),
  mailboxes: z.coerce.number().int().min(1).max(100000),
  storageGB: z.coerce.number().int().min(1).max(100000),
  priceCents: z.coerce.number().int().min(0).max(100000000),
  termMonths: z.coerce.number().int().min(1).max(36),
  sortOrder: z.coerce.number().int().min(0).max(100000),
});

/** Create or update an EmailPlan tier. ADMIN/BILLING only, audit-logged. */
export async function adminSaveEmailPlan(
  prev: Result | undefined,
  formData: FormData,
): Promise<Result> {
  const admin = await requireArea("billing");

  const parsed = planSchema.safeParse({
    id: formData.get("id") || undefined,
    name: formData.get("name"),
    mailboxes: formData.get("mailboxes"),
    storageGB: formData.get("storageGB"),
    priceCents: formData.get("priceCents"),
    termMonths: formData.get("termMonths"),
    sortOrder: formData.get("sortOrder") ?? 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
  }
  const d = parsed.data;
  const active = formData.get("active") === "on";

  const data = {
    name: d.name.trim(),
    mailboxes: d.mailboxes,
    storageGB: d.storageGB,
    priceCents: d.priceCents,
    termMonths: d.termMonths,
    active,
    sortOrder: d.sortOrder,
  };

  if (d.id) {
    const existing = await db.emailPlan.findUnique({ where: { id: d.id } });
    if (!existing) return { error: "Tier not found." };
    await db.emailPlan.update({ where: { id: d.id }, data });
  } else {
    await db.emailPlan.create({ data });
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: d.id ? "emailplan.update" : "emailplan.create",
      detail: `${data.name} — ${data.mailboxes} mbx / ${data.storageGB}GB (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
    },
  });
  revalidatePath("/admin/email-plans");
  return { ok: true };
}

/** Flip a tier's active flag. */
export async function adminToggleEmailPlan(id: string): Promise<void> {
  const admin = await requireArea("billing");
  const plan = await db.emailPlan.findUnique({ where: { id } });
  if (!plan) return;
  await db.emailPlan.update({ where: { id }, data: { active: !plan.active } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "emailplan.toggle", detail: `${plan.name} → active=${!plan.active}` },
  });
  revalidatePath("/admin/email-plans");
}

/** Delete a tier. Refused while subscriptions reference it. */
export async function adminDeleteEmailPlan(id: string): Promise<Result> {
  const admin = await requireArea("billing");
  const plan = await db.emailPlan.findUnique({
    where: { id },
    include: { _count: { select: { subscriptions: true } } },
  });
  if (!plan) return { error: "Tier not found." };
  if (plan._count.subscriptions > 0) {
    return {
      error: `Can't delete — ${plan._count.subscriptions} subscription(s) use this tier. Disable it instead.`,
    };
  }
  await db.emailPlan.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "emailplan.delete", detail: plan.name },
  });
  revalidatePath("/admin/email-plans");
  return { ok: true };
}

// ---------- Customer ordering ----------

/**
 * Subscribe one of the caller's registered domains to an email plan. Validates
 * domain ownership + plan availability, then atomically debits the wallet and
 * creates the EmailSubscription with an expiry set from the plan term.
 *
 * The subscription is created ACTIVE (billing-wise), but no mailboxes are
 * provisioned with a mail provider yet — that integration is pending, and the
 * UI surfaces every mailbox as "provisioning" until it lands.
 */
export async function orderEmailHosting(
  domainName: string,
  emailPlanId: string,
): Promise<Result> {
  const user = await requireUser();

  const name = String(domainName ?? "").trim().toLowerCase();
  if (!name) return { error: "Choose a domain." };

  // Ownership check — the domain must be registered to this user.
  const domain = await db.domain.findFirst({ where: { name, userId: user.id } });
  if (!domain) return { error: "That domain isn't in your account." };

  const plan = await db.emailPlan.findUnique({ where: { id: emailPlanId } });
  if (!plan || !plan.active) return { error: "That email plan isn't available." };

  // One subscription per domain — refuse a duplicate.
  const dupe = await db.emailSubscription.findFirst({
    where: { userId: user.id, domainName: name, status: { not: "CANCELLED" } },
  });
  if (dupe) return { error: "This domain already has an email subscription." };

  const chargeCents = plan.priceCents;
  if (user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  try {
    await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Business Email: ${plan.name} for ${name}`,
        },
      });
      await tx.emailSubscription.create({
        data: {
          userId: user.id,
          domainName: name,
          emailPlanId: plan.id,
          status: "ACTIVE",
          autoRenew: true,
          expiresAt: addMonths(new Date(), plan.termMonths),
        },
      });
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "emailhosting.order",
      detail: `${name} plan=${plan.name}`,
    },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;

/**
 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
 * quota and address uniqueness within the subscription, records the intended
 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
 */
export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({
    where: { id: subscriptionId },
    include: { emailPlan: true, mailboxes: true },
  });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };
  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };

  const local = String(localPart ?? "").trim().toLowerCase();
  if (!localPartRe.test(local) || local.length > 64) {
    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
  }

  const address = `${local}@${sub.domainName}`;

  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
    return {
      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
    };
  }
  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
    return { error: "That address already exists." };
  }

  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
  const quotaMB = sub.emailPlan.storageGB * 1024;

  const mailbox = await db.mailbox.create({
    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.add", detail: address },
  });

  // Additive, failure-tolerant provisioning — never throws out of the flow.
  await provisionMailboxOnMailcow({
    id: mailbox.id,
    address: mailbox.address,
    quotaMB,
    subscription: { domainName: sub.domainName },
  });

  revalidatePath("/dashboard/email");
  return { ok: true };
}

/**
 * Re-attempt Mailcow provisioning for a mailbox stuck in PROVISIONING/FAILED.
 * Owner-only (the caller must own the mailbox via its subscription).
 */
export async function retryMailboxProvision(mailboxId: string): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };

  await db.mailbox.update({ where: { id: mailbox.id }, data: { status: "PROVISIONING" } });

  const status = await provisionMailboxOnMailcow({
    id: mailbox.id,
    address: mailbox.address,
    quotaMB: mailbox.quotaMB,
    subscription: { domainName: mailbox.subscription.domainName },
  });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.retry", detail: `${mailbox.address} → ${status}` },
  });
  revalidatePath("/dashboard/email");

  if (status === "FAILED") return { error: "Provisioning failed again — check the mail server." };
  return { ok: true };
}

/** Remove a mailbox the caller owns (via its subscription). */
export async function removeMailbox(mailboxId: string): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };

  // Best-effort delete on Mailcow before dropping the row — a mail-server outage
  // must not block the customer from removing the mailbox record.
  if (mailcowConfigured()) {
    await mcDeleteMailbox(mailbox.address).catch((e) => {
      console.warn(`[mailcow] delete ${mailbox.address} failed:`, e);
    });
  }

  await db.mailbox.delete({ where: { id: mailbox.id } });

  await db.auditLog.create({
    data: { userId: user.id, action: "mailbox.remove", detail: mailbox.address },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

/**
 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
 */
export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
  const user = await requireUser();

  const mailbox = await db.mailbox.findUnique({
    where: { id: mailboxId },
    include: { subscription: true },
  });
  if (!mailbox) return { error: "Mailbox not found." };
  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };

  if (mailcowConfigured()) {
    await mcSetMailboxActive(mailbox.address, !suspended).catch((e) => {
      console.warn(`[mailcow] set active ${mailbox.address} failed:`, e);
    });
  }

  await db.mailbox.update({
    where: { id: mailbox.id },
    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
  });

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: suspended ? "mailbox.suspend" : "mailbox.resume",
      detail: mailbox.address,
    },
  });
  revalidatePath("/dashboard/email");
  return { ok: true };
}

