/**
 * Seasonal / promotional pricing — HONEST intro-discount model.
 *
 * The whole design is an INTRO DISCOUNT: a promo discounts a customer's FIRST
 * TERM only. The "regular" (strikethrough) price is the genuine renewal price;
 * the "promo" price is the genuine first-term price. BOTH are real charges —
 * never a fabricated former price and never a bait-and-switch. The discounted
 * price shown must equal what checkout charges (see promoPriceCents usage in
 * lib/order.ts, lib/actions.ts and lib/actions-email-hosting.ts). Renewal paths
 * (worker/billing.ts, worker/product-renewals.ts) are left untouched, so
 * renewals bill the regular price — exactly what the strikethrough promises.
 *
 * Countdowns use promoEndsAt(), which returns the promo window's REAL close
 * date. Promos genuinely rotate by calendar date; a new one may begin after the
 * current one ends, but the current one truly ends when the timer says.
 *
 * Pure & deterministic: every helper takes `now` as a parameter. Nothing here
 * calls Date.now() at module load, so it is safe to import anywhere (including
 * server components that render it at request time).
 */

export type Promo = {
  id: string;
  /** Full name, e.g. "Summer Sale". */
  name: string;
  /** Short badge text, e.g. "Summer Sale". */
  label: string;
  /** Percent off the FIRST-term charge (0–100). */
  discountPercent: number;
  /** Window open, inclusive, "MM-DD". */
  start: string;
  /** Window close, inclusive, "MM-DD" (may wrap the year end). */
  end: string;
};

/**
 * Rotating seasonal promos. Checked in array order; the first promo whose
 * calendar window covers `now` wins. Windows are real dates — the countdown a
 * customer sees is the true close of the active window.
 */
export const SEASONAL_PROMOS: Promo[] = [
  { id: "new-year",       name: "New Year Sale",       label: "New Year Sale",   discountPercent: 30, start: "01-01", end: "01-07" },
  { id: "valentines",     name: "Valentine's Sale",    label: "Valentine's Sale", discountPercent: 20, start: "02-08", end: "02-16" },
  { id: "spring",         name: "Spring Sale",         label: "Spring Sale",     discountPercent: 25, start: "03-20", end: "04-05" },
  { id: "summer",         name: "Summer Sale",         label: "Summer Sale",     discountPercent: 30, start: "06-21", end: "08-10" },
  { id: "back-to-school", name: "Back-to-School Sale", label: "Back-to-School",  discountPercent: 25, start: "08-15", end: "09-15" },
  { id: "halloween",      name: "Halloween Sale",      label: "Halloween Sale",  discountPercent: 25, start: "10-24", end: "10-31" },
  { id: "black-friday",   name: "Black Friday",        label: "Black Friday",    discountPercent: 40, start: "11-24", end: "11-30" },
  { id: "cyber-monday",   name: "Cyber Monday",        label: "Cyber Monday",    discountPercent: 45, start: "12-01", end: "12-02" },
  { id: "holiday",        name: "Holiday Sale",        label: "Holiday Sale",    discountPercent: 35, start: "12-15", end: "12-31" },
];

/**
 * Always-on modest fallback so there is ALWAYS an active promo between seasons.
 * Its real end date is the start of the next seasonal promo (see promoEndsAt) —
 * an honest "the Launch Sale runs until the next sale begins".
 */
export const LAUNCH_SALE: Promo = {
  id: "launch",
  name: "Launch Sale",
  label: "Launch Sale",
  discountPercent: 15,
  start: "01-01",
  end: "12-31",
};

/** Build a concrete Date for a given year + "MM-DD" (local time). */
function dateAt(year: number, mmdd: string, endOfDay: boolean): Date {
  const [m, d] = mmdd.split("-").map(Number);
  return endOfDay
    ? new Date(year, m - 1, d, 23, 59, 59, 999)
    : new Date(year, m - 1, d, 0, 0, 0, 0);
}

/**
 * Resolve a promo's window to the concrete [start, end] occurrence around `now`,
 * correctly handling a window that wraps the year boundary (e.g. 12-28..01-03).
 */
function windowBounds(now: Date, promo: Promo): { start: Date; end: Date } {
  const y = now.getFullYear();
  let start = dateAt(y, promo.start, false);
  let end = dateAt(y, promo.end, true);
  if (end < start) {
    // Wrapping window: pick the occurrence that surrounds `now`.
    if (now >= start) end = dateAt(y + 1, promo.end, true); // December side
    else start = dateAt(y - 1, promo.start, false); // January side
  }
  return { start, end };
}

function inWindow(now: Date, promo: Promo): boolean {
  const { start, end } = windowBounds(now, promo);
  return now >= start && now <= end;
}

/** Earliest upcoming seasonal-promo start strictly after `now`. */
function nextSeasonalStart(now: Date): Date {
  const y = now.getFullYear();
  let best: Date | null = null;
  for (const p of SEASONAL_PROMOS) {
    // Consider this year's and next year's occurrence so year-end wraps around.
    for (const yr of [y, y + 1]) {
      const s = dateAt(yr, p.start, false);
      if (s > now && (!best || s < best)) best = s;
    }
  }
  return best ?? dateAt(y + 1, SEASONAL_PROMOS[0].start, false);
}

/**
 * The active promo for `now`: the first seasonal promo whose window covers it,
 * or the always-on Launch Sale fallback. Never returns null — there is always a
 * genuine, honest promo running.
 */
export function currentPromo(now: Date): Promo {
  for (const p of SEASONAL_PROMOS) {
    if (inWindow(now, p)) return p;
  }
  return LAUNCH_SALE;
}

/**
 * The genuine first-term price for a regular price under `promo`.
 * round(regularCents * (1 - discountPercent/100)). This exact value is what
 * checkout charges for the first term — display it verbatim.
 */
export function promoPriceCents(regularCents: number, promo: Promo): number {
  return Math.round(regularCents * (1 - promo.discountPercent / 100));
}

/**
 * The REAL Date the current promo window closes (drives the countdown).
 *  - A seasonal promo: the end instant of its active window.
 *  - The Launch Sale fallback: genuinely ends when the next seasonal promo
 *    begins (the next sale takes over), so the countdown is truthful.
 */
export function promoEndsAt(now: Date, promo: Promo): Date {
  if (promo.id === LAUNCH_SALE.id) return nextSeasonalStart(now);
  return windowBounds(now, promo).end;
}

"use client";

import { useEffect, useState } from "react";

/** Format a remaining-milliseconds span as "2d 4h 10m" / "4h 10m 5s" / "10m 5s". */
function fmt(ms: number): string {
  const totalSec = Math.max(0, Math.floor(ms / 1000));
  const d = Math.floor(totalSec / 86400);
  const h = Math.floor((totalSec % 86400) / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  const parts: string[] = [];
  if (d) parts.push(`${d}d`);
  if (d || h) parts.push(`${h}h`);
  parts.push(`${m}m`);
  if (!d) parts.push(`${s}s`); // seconds only matter once we're inside a day
  return parts.join(" ");
}

/**
 * Live promo countdown. `endsAt` is the real ISO close date of the active promo
 * (from promoEndsAt). Ticks every second; shows a stable placeholder before the
 * client mounts to avoid hydration mismatch.
 */
export function PromoCountdown({
  endsAt,
  prefix = "ends in",
  className = "",
}: {
  endsAt: string;
  prefix?: string;
  className?: string;
}) {
  const end = Date.parse(endsAt);
  const [remaining, setRemaining] = useState<number | null>(null);

  useEffect(() => {
    const tick = () => setRemaining(end - Date.now());
    tick();
    const t = setInterval(tick, 1000);
    return () => clearInterval(t);
  }, [end]);

  if (remaining === null) {
    return (
      <span className={className} suppressHydrationWarning>
        {prefix} …
      </span>
    );
  }
  if (remaining <= 0) {
    // Promos rotate by calendar date; the next one is taking over.
    return <span className={className}>Refreshing…</span>;
  }
  return (
    <span className={className} suppressHydrationWarning>
      {prefix} {fmt(remaining)}
    </span>
  );
}

import type { Promo } from "@/lib/promotions";

/**
 * Small promo pill — "<Sale> · X% off". Plain server-safe component (no client
 * runtime); compose it with <PromoCountdown> for the live timer.
 */
export function PromoBadge({ promo, className = "" }: { promo: Promo; className?: string }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full border border-brand-500/30 bg-brand-500/15 px-2.5 py-0.5 text-[11px] font-semibold uppercase tracking-[0.12em] text-brand-200 ${className}`}
    >
      <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan" aria-hidden />
      {promo.label} · {promo.discountPercent}% off
    </span>
  );
}

import { currentPromo, promoEndsAt, promoPriceCents } from "@/lib/promotions";
import { PromoCountdown } from "./PromoCountdown";

/**
 * Optional slim site-wide promo bar. Server component — reads the active promo
 * at request time and renders an honest intro-discount strip with a live
 * countdown. NOT mounted here: the layout orchestrator decides where to mount it
 * (e.g. above the marketing header). Safe to drop into any server layout.
 *
 * Honest by construction: it advertises "X% off your first term" and the promo's
 * real end date — it never claims a fake former price or a countdown that resets.
 */
export function PromoBar() {
  const now = new Date();
  const promo = currentPromo(now);
  const endsAt = promoEndsAt(now, promo).toISOString();
  // Illustrative: our entry VPS regularly bills $5/mo; show the honest first-term
  // price so the bar's headline number matches what checkout charges.
  const exampleRegular = 500;
  const exampleFirst = promoPriceCents(exampleRegular, promo);

  return (
    <div className="w-full border-b border-brand-500/20 bg-gradient-to-r from-accent-blue/15 via-brand-500/15 to-accent-blue/15">
      <div className="mx-auto flex max-w-6xl flex-wrap items-center justify-center gap-x-3 gap-y-1 px-4 py-2 text-center text-[13px] text-slate-200">
        <span className="font-semibold text-white">{promo.name}</span>
        <span aria-hidden className="text-slate-500">·</span>
        <span>
          <span className="font-semibold grad-text">{promo.discountPercent}% off your first term</span> —
          VPS from <span className="text-slate-400 line-through">${(exampleRegular / 100).toFixed(0)}</span>{" "}
          <span className="font-semibold text-white">${(exampleFirst / 100).toFixed(2)}/mo</span>, renews at ${(exampleRegular / 100).toFixed(0)}/mo.
        </span>
        <span aria-hidden className="text-slate-500">·</span>
        <PromoCountdown endsAt={endsAt} prefix={`${promo.name} ends in`} className="font-semibold text-brand-200" />
      </div>
    </div>
  );
}

