 {id:"cyber-monday",start:"12-01",end:"12-02",d:45},
 {id:"holiday",start:"12-15",end:"12-31",d:35},
];
const LAUNCH={id:"launch",start:"01-01",end:"12-31",d:15};
const dateAt=(y,mmdd,eod)=>{const[m,d]=mmdd.split("-").map(Number);return eod?new Date(y,m-1,d,23,59,59,999):new Date(y,m-1,d,0,0,0,0);};
function bounds(now,p){const y=now.getFullYear();let s=dateAt(y,p.start,false),e=dateAt(y,p.end,true);if(e<s){if(now>=s)e=dateAt(y+1,p.end,true);else s=dateAt(y-1,p.start,false);}return{s,e};}
const inW=(now,p)=>{const{s,e}=bounds(now,p);return now>=s&&now<=e;};
function nextStart(now){const y=now.getFullYear();let best=null;for(const p of SEASONAL)for(const yr of[y,y+1]){const s=dateAt(yr,p.start,false);if(s>now&&(!best||s<best))best=s;}return best;}
function cur(now){for(const p of SEASONAL)if(inW(now,p))return p;return LAUNCH;}
function endsAt(now,p){return p.id===LAUNCH.id?nextStart(now):bounds(now,p).e;}
const price=(c,p)=>Math.round(c*(1-p.d/100));
